{
  "name": "真实USB设备通信组件",
  "name_en": "Real USB Device Communication Component",
  "manufacturer": "",
  "description": "一个非物理的软件组件，用于在实验系统中直接访问通用USB设备。它提供设备查找、USB配置设置、设备复位、接口占用与释放、控制传输、原始数据读取等功能，适合与未专门建模的USB实验设备或自定义硬件进行底层通信。",
  "description_en": "A non-physical software component for direct access to generic USB devices in laboratory systems. It provides device discovery, USB configuration, device reset, interface claim/release, control transfers, and raw data reads, making it suitable for low-level communication with custom hardware or USB-based lab equipment that is not otherwise specifically modeled.",
  "tag_hints": [
    "USB communication",
    "low-level device access",
    "control transfer",
    "raw USB readout",
    "interface claim/release",
    "custom hardware integration"
  ],
  "actions": [
    {
      "action_name": "auto-find",
      "description": "查找并定位可用的USB设备，以便后续通信。",
      "description_en": "Find and locate an available USB device for subsequent communication."
    },
    {
      "action_name": "auto-set_configuration",
      "description": "为目标USB设备设置活动配置。",
      "description_en": "Set the active configuration for the target USB device."
    },
    {
      "action_name": "auto-reset",
      "description": "复位USB设备，重新初始化其连接或状态。",
      "description_en": "Reset the USB device to reinitialize its connection or state."
    },
    {
      "action_name": "auto-claim_interface",
      "description": "占用指定USB接口，以获得独占通信访问。",
      "description_en": "Claim a specified USB interface to obtain exclusive communication access."
    },
    {
      "action_name": "auto-release_interface",
      "description": "释放先前占用的USB接口。",
      "description_en": "Release a previously claimed USB interface."
    },
    {
      "action_name": "auto-ctrl_transfer",
      "description": "执行USB控制传输，用于发送底层控制请求或接收响应。",
      "description_en": "Perform a USB control transfer to send low-level control requests or receive responses."
    },
    {
      "action_name": "auto-read",
      "description": "从USB端点读取原始数据。",
      "description_en": "Read raw data from a USB endpoint."
    },
    {
      "action_name": "auto-send_code",
      "description": "向USB设备发送代码、命令或预定义数据序列。",
      "description_en": "Send code, commands, or a predefined data sequence to the USB device."
    },
    {
      "action_name": "auto-to_dict",
      "description": "将当前设备信息导出为字典结构，便于记录或调试。",
      "description_en": "Export the current device information as a dictionary for logging or debugging."
    }
  ]
}

